//! Luck — вопрос §4.1 из MARKER_V0_RUST.md: «Даёт ли переход к настоящему
//! radix-дереву выигрыш, оправдывающий сложность?»
//! Ветка: Rust-проход (Маркер В.0 -> возврат)
//!
//! ЧТО ЭТО ИЗМЕРЯЕТ, А ЧТО НЕТ.
//! Это НЕ реализация RadixAttention и не замена ComputationCache в
//! scheduler.rs (там кэш — по составному ключу, точное совпадение всего
//! промпта; менять не нужно, он и так корректен). Это измерительный
//! инструмент: строит дерево по СТРОКАМ промпта (не токенам — токенизатор
//! у нас не свой) и считает, сколько байт промпта повторяется как общий
//! префикс между узлами графа с общим путём предков.
//!
//! ПОЧЕМУ ЭТО ЧЕСТНЫЙ ОТВЕТ, А НЕ ПОДМЕНА ВОПРОСА. Текстовое совпадение
//! префикса — необходимое, но не достаточное условие выигрыша настоящего
//! KV-кэша (тот работает на токенах, не строках; реальная токенизация
//! может резать по-другому на границе). Но обратное строго: если ТЕКСТ
//! не разделяет общих префиксов между промптами, соответствующие токены
//! тем более не совпадут — токенизация только дробит существующее
//! совпадение мельче, не создаёт нового. Поэтому измерение здесь —
//! верхняя граница выигрыша, и если верхняя граница мала, вопрос закрыт
//! отрицательно без необходимости в реальном движке; если велика — вопрос
//! остаётся открытым (нужен реальный токенизатор), но появляется довод
//! ЗА, а не спекуляция.

use std::collections::BTreeMap;

#[derive(Default)]
struct TrieNode {
    children: BTreeMap<String, TrieNode>,
}

/// Дерево общих префиксов промптов, разбитых на строки. Строка — тот же
/// разделитель, что использует `Scheduler::build_prompt` для склейки
/// поверхностного синтаксиса предков (`"\n"`), поэтому граница строки
/// здесь совпадает с границей "один узел = один смысловой блок
/// префикса" — та самая единица, которую и рассчитан переиспользовать
/// префиксный KV-кэш инференс-движка.
#[derive(Default)]
pub struct PrefixTrie {
    root: TrieNode,
    /// Сколько РАЗ строка была вставлена как продолжение уже
    /// существующего пути (= сколько раз реальный radix-кэш отдал бы
    /// готовый расчёт вместо повторного).
    pub shared_lines: usize,
    /// Сколько раз строка была вставлена как НОВЫЙ узел дерева.
    pub new_lines: usize,
    /// Суммарная длина (в байтах) всех вставленных промптов, если бы
    /// каждый считался независимо, без переиспользования префикса.
    pub bytes_if_independent: usize,
    /// Суммарная длина (в байтах) РЕАЛЬНО хранимых в дереве строк —
    /// то, что осталось бы вычислить при переиспользовании префикса.
    pub bytes_stored: usize,
}

impl PrefixTrie {
    pub fn new() -> Self {
        Self::default()
    }

    /// Вставляет промпт (уже готовый текст, как его строит
    /// `Scheduler::build_prompt`). Возвращает (shared, new) для ЭТОЙ
    /// вставки — сколько строк промпта уже были в дереве (совпадение
    /// префикса с ранее вставленным промптом) и сколько добавлено новых.
    pub fn insert(&mut self, prompt: &str) -> (usize, usize) {
        let lines: Vec<&str> = prompt.split('\n').collect();
        self.bytes_if_independent += prompt.len();

        let mut node = &mut self.root;
        let mut shared = 0;
        let mut new = 0;
        let sep_count = lines.len().saturating_sub(1);
        for (i, line) in lines.iter().enumerate() {
            if node.children.contains_key(*line) {
                shared += 1;
            } else {
                new += 1;
                // Разделитель '\n' считаем ровно (lines.len() - 1) раз на
                // промпт — столько же, сколько реально в prompt.len() —
                // чтобы bytes_stored никогда не мог превысить
                // bytes_if_independent на графе без общих префиксов.
                self.bytes_stored += line.len() + usize::from(i < sep_count);
                node.children
                    .insert((*line).to_string(), TrieNode::default());
            }
            node = node.children.get_mut(*line).unwrap();
        }

        self.shared_lines += shared;
        self.new_lines += new;
        (shared, new)
    }

    /// Доля промпта, которая была бы пересчитана заново БЕЗ дерева
    /// (upper bound выигрыша от radix-подобного кэша, см. докстринг
    /// модуля — это необходимое, не достаточное условие реальной выгоды).
    pub fn savings_ratio(&self) -> f64 {
        if self.bytes_if_independent == 0 {
            return 0.0;
        }
        1.0 - (self.bytes_stored as f64 / self.bytes_if_independent as f64)
    }
}
